// Package constgen generates Go constants for the icon names in a directory.
package constgen

import (
	"bytes"
	"fmt"
	"go/format"
	"go/token"
	"io/fs"
	"slices"
	"strings"
	"unicode"
)

// Case controls how name segments are turned into identifier parts.
type Case int

const (
	// Camel turns "arrow-up-left" into "ArrowUpLeft".
	Camel Case = iota
	// Upper turns "gb-eng" into "GB_ENG".
	Upper
)

// Config describes one generated file.
type Config struct {
	Package string // package clause of the generated file
	Dir     string // directory in FS holding the *.svg files
	Prefix  string // identifier prefix, e.g. "Icon"
	Case    Case
	Command string // command line recorded in the file header
}

// Generate returns a gofmt-formatted Go file declaring one untyped string
// constant per *.svg file in cfg.Dir.
func Generate(fsys fs.FS, cfg Config) ([]byte, error) {
	if !token.IsIdentifier(cfg.Package) {
		return nil, fmt.Errorf("invalid package name %q", cfg.Package)
	}
	entries, err := fs.ReadDir(fsys, cfg.Dir)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".svg") {
			names = append(names, strings.TrimSuffix(e.Name(), ".svg"))
		}
	}
	if len(names) == 0 {
		return nil, fmt.Errorf("no *.svg files in %q", cfg.Dir)
	}
	slices.Sort(names)

	var buf bytes.Buffer
	fmt.Fprintf(&buf, "// Code generated by %s; DO NOT EDIT.\n\n", cfg.Command)
	fmt.Fprintf(&buf, "package %s\n\n", cfg.Package)
	fmt.Fprintf(&buf, "// Names of all %d icons in this package.\nconst (\n", len(names))

	seen := make(map[string]string, len(names))
	for _, name := range names {
		ident, err := Identifier(cfg.Prefix, name, cfg.Case)
		if err != nil {
			return nil, err
		}
		if other, dup := seen[ident]; dup {
			return nil, fmt.Errorf("icons %q and %q both map to identifier %s", other, name, ident)
		}
		seen[ident] = name
		fmt.Fprintf(&buf, "\t%s = %q\n", ident, name)
	}
	buf.WriteString(")\n")

	return format.Source(buf.Bytes())
}

// Identifier converts an icon name into an exported Go identifier.
// Any character that is not a letter or digit separates segments.
func Identifier(prefix, name string, c Case) (string, error) {
	segments := strings.FieldsFunc(name, func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r)
	})
	if len(segments) == 0 {
		return "", fmt.Errorf("icon name %q has no usable characters", name)
	}

	var ident string
	switch c {
	case Upper:
		ident = strings.ToUpper(strings.Join(segments, "_"))
	default:
		for _, s := range segments {
			ident += strings.ToUpper(s[:1]) + s[1:]
		}
	}
	ident = prefix + ident

	if !token.IsIdentifier(ident) || !token.IsExported(ident) {
		return "", fmt.Errorf("icon name %q does not yield an exported identifier (%s); use a prefix", name, ident)
	}
	return ident, nil
}
